#!/usr/bin/env python3
"""Regenerate deterministic ground truth for CSX-311_Q1."""

from __future__ import annotations

import json
import re
from html import unescape
from pathlib import Path
from typing import Any


TASK_ID = "CSX-311_Q1"
EVENT_ID = "CSX-311"
TARGET_FAMILY = "ontake_phreatic_rain_gate_consistency"
RAIN_THRESHOLD_MM = 1.0


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig", errors="replace")


def clean_html(fragment: str) -> str:
    text = re.sub(r"<[^>]+>", " ", fragment)
    text = unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def find_event_paragraph(html: str) -> str:
    for match in re.finditer(r"<p\b[^>]*>(.*?)</p>", html, flags=re.IGNORECASE | re.DOTALL):
        paragraph = clean_html(match.group(1))
        lowered = paragraph.lower()
        if "phreatic eruption" in lowered and "hikers" in lowered:
            return paragraph
    raise ValueError("Could not find the Ontake event paragraph")


def count_term(text: str, term: str) -> int:
    if " " in term:
        pattern = r"(?<![A-Za-z0-9])" + r"\s+".join(re.escape(part) for part in term.split()) + r"(?![A-Za-z0-9])"
    else:
        pattern = r"\b" + re.escape(term) + r"\b"
    return len(re.findall(pattern, text, flags=re.IGNORECASE))


def precip_values(package_dir: Path) -> dict[str, float]:
    nasa = read_json(package_dir / "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json")
    open_meteo = read_json(package_dir / "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json")
    era5 = read_json(package_dir / "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json(package_dir / "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json(package_dir / "data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json")

    return {
        "nasa_power_mm": float(nasa["properties"]["parameter"]["PRECTOTCORR"]["20140927"]),
        "open_meteo_mm": float(open_meteo["daily"]["precipitation_sum"][0]),
        "era5_land_max_mm": float(era5["stats"]["precipitation_sum_mm_max"]),
        "gpm_imerg_max_mm": float(gpm["stats"]["gpm_event_precip_mm_max"]),
        "chirps_max_mm": float(chirps["stats"]["chirps_event_precip_mm_max"]),
    }


def reported_hiker_count(text: str) -> int:
    match = re.search(r"\bAs many as\s+(\d+)\s+hikers\b", text, flags=re.IGNORECASE)
    if not match:
        raise ValueError("Could not extract reported hiker count")
    return int(match.group(1))


def scoring_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Output schema",
                "points": 3,
                "description": "Returns compact JSON with answer, max_precip_mm, dry_margin_mm, sources_below_1mm, anchor_score, reported_hikers, rain_gate, and one calculation-tied note.",
            },
            {
                "name": "Precipitation aggregation",
                "points": 5,
                "description": "Computes max_precip_mm as 0.536591 mm from the five event-day precipitation summaries, dry_margin_mm as 0.463409 mm, and sources_below_1mm as 5.",
            },
            {
                "name": "Narrative anchor extraction",
                "points": 5,
                "description": "Uses exact whole-word or phrase counting to get phreatic=2, ash=2, ballistic=1, hikers=1, little_warning=1, unexpectedly=1, anchor_score=8, and reported_hikers=36.",
            },
            {
                "name": "Threshold proof",
                "points": 4,
                "description": "Applies the 1.0 mm rain threshold, marks rain_gate as fail_lt_1mm, and returns the label phreatic_report_dry_window.",
            },
            {
                "name": "Concise consequence",
                "points": 2,
                "description": "Keeps the interpretation to a short computed consequence and avoids extra inferences beyond the threshold and count results.",
            },
            {
                "name": "Units and rounding",
                "points": 1,
                "description": "Reports millimeter values to about 1e-6 precision or an equivalent clearly rounded tolerance.",
            },
        ],
    }


def build_result(package_dir: Path) -> dict[str, Any]:
    event = read_json(package_dir / "metadata/event.json")
    anchor = read_json(package_dir / "data/event_reports/event_reports_003_Locked_event_anchor_Mount_Ontake_eruption.json")
    html = read_text(package_dir / "data/event_reports/event_reports_001_Locked_package_evidence_report.html")
    paragraph = find_event_paragraph(html)
    narrative_text = paragraph + " " + anchor["locked_event_anchor"]["event_lock_notes"]

    precipitation = precip_values(package_dir)
    max_precip = max(precipitation.values())
    dry_margin = RAIN_THRESHOLD_MM - max_precip
    sources_below = sum(value < RAIN_THRESHOLD_MM for value in precipitation.values())

    anchor_counts = {
        "phreatic": count_term(narrative_text, "phreatic"),
        "ash": count_term(narrative_text, "ash"),
        "ballistic": count_term(narrative_text, "ballistic"),
        "hikers": count_term(narrative_text, "hikers"),
        "little_warning": count_term(narrative_text, "little warning"),
        "unexpectedly": count_term(narrative_text, "unexpectedly"),
    }
    anchor_score = sum(anchor_counts.values())
    hikers = reported_hiker_count(paragraph)
    rain_gate = "fail_lt_1mm" if max_precip < RAIN_THRESHOLD_MM else "pass_ge_1mm"
    answer = (
        "phreatic_report_dry_window"
        if rain_gate == "fail_lt_1mm" and anchor_score >= 6 and hikers > 0
        else "rain_gate_or_anchor_check_not_met"
    )
    consistency_note = (
        "All five event-day precipitation summaries are below 1 mm while the phreatic narrative "
        "anchor score is 8, so the computed label is phreatic_report_dry_window."
    )

    primary_gt = {
        "answer": answer,
        "max_precip_mm": round(max_precip, 6),
        "dry_margin_mm": round(dry_margin, 6),
        "sources_below_1mm": sources_below,
        "anchor_score": anchor_score,
        "reported_hikers": hikers,
        "rain_gate": rain_gate,
        "consistency_note": consistency_note,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "event_date": anchor["temporal_window"]["start_date"],
            "hazard_family": event["hazard_family"],
            "rain_threshold_mm": RAIN_THRESHOLD_MM,
            "precipitation_mm": {key: round(value, 6) for key, value in precipitation.items()},
            "anchor_counts": anchor_counts,
            "narrative_terms_scored": list(anchor_counts),
        },
        "tolerances": {
            "max_precip_mm": 1e-6,
            "dry_margin_mm": 1e-6,
            "integer_counts": 0,
        },
        "decision_rule": {
            "precip_formula": "max_precip_mm=max(five event-day precipitation summaries)",
            "dry_margin_formula": "dry_margin_mm=1.0-max_precip_mm",
            "anchor_score_formula": "sum exact counts for phreatic, ash, ballistic, hikers, little warning, unexpectedly",
            "label_rule": "phreatic_report_dry_window when max_precip_mm<1.0, anchor_score>=6, and reported_hikers>0",
            "determinism": "fixed local files, explicit regular expressions, fixed threshold, and stated numeric tolerances",
        },
        "rubric": scoring_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
                "data/event_reports/event_reports_003_Locked_event_anchor_Mount_Ontake_eruption.json",
                "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json",
                "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json",
                "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
                "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
                "data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json",
            ],
        },
    }


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
    result = build_result(package_dir)
    (task_dir / "computed_gt.json").write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
